1	// TD Bank Credit Card CSV Parser
2	// Expected format: Date,Description,Amount,[Credit Column]
3	// Date format: MM/DD/YYYY
4	// Amount: Debits are positive, Credits have value in 4th column
5	// No header row in the CSV
6	
7	import { BaseCSVParser } from './BaseCSVParser';
8	import type { CSVParseResult, ParsedTransaction } from '$lib/models/Transaction';
9	
10	export class TDBankParser extends BaseCSVParser {
11		parse(csvContent: string): CSVParseResult {
12			const transactions: ParsedTransaction[] = [];
13			const errors: string[] = [];
14	
15			try {
16				csvContent = this.removeBOM(csvContent);
17				const rows = this.parseCSV(csvContent);
18	
19				if (rows.length < 1) {
20					errors.push('CSV file is empty or has no data rows');
21					return { transactions, errors };
22				}
23	
24				// TD Bank CSV has no header row, starts directly with data
25				// Format: Date,Description,Amount[,Credit Amount]
26				// If there are 4 columns and the 4th has a value, it's a credit (positive)
27				// If there are 3 columns or 4th column is empty, the amount in column 3 is a debit (negative)
28	
29				for (let i = 0; i < rows.length; i++) {
30					const row = rows[i];
31					if (row.length < 3) continue; // Skip incomplete rows
32	
33					const dateStr = row[0]?.trim();
34					const description = row[1]?.trim();
35					const debitAmountStr = row[2]?.trim();
36					const creditAmountStr = row.length > 3 ? row[3]?.trim() : '';
37	
38					// Skip empty rows
39					if (!dateStr && !description && !debitAmountStr) continue;
40	
41					// Parse date
42					const transaction_date = this.parseDate(dateStr);
43					if (!transaction_date) {
44						errors.push(`Row ${i + 1}: Invalid date format "${dateStr}"`);
45						continue;
46					}
47	
48					// Determine amount (credit or debit)
49					let rawAmount: number | null = null;
50					if (creditAmountStr) {
51						// It's a credit (deposit/refund) - originally positive
52						rawAmount = this.parseAmount(creditAmountStr);
53					} else if (debitAmountStr) {
54						// It's a debit (expense/purchase) - make negative for normalization
55						const parsedDebit = this.parseAmount(debitAmountStr);
56						if (parsedDebit !== null) {
57							rawAmount = -Math.abs(parsedDebit); // Ensure it's negative
58						}
59					}
60	
61					if (rawAmount === null) {
62						errors.push(
63							`Row ${i + 1}: Invalid amount (debit: "${debitAmountStr}", credit: "${creditAmountStr}")`
64						);
65						continue;
66					}
67	
68					// TD Bank uses negative for expenses — keep as-is (#{#trn2e})
69					const amount = this.normalizeAmount(rawAmount, false);
70	
71					// Validate description
72					if (!description) {
73						errors.push(`Row ${i + 1}: Missing vendor name/description`);
74						continue;
75					}
76	
77					transactions.push({
78						transaction_date,
79						vendor_name: description,
80						amount
81					});
82				}
83			} catch (e: any) {
84				errors.push(`Failed to parse CSV: ${e.message || 'Unknown error'}`);
85			}
86	
87			return { transactions, errors };
88		}
89	
90		validateFormat(csvContent: string): boolean {
91			try {
92				csvContent = this.removeBOM(csvContent);
93				const rows = this.parseCSV(csvContent);
94				if (rows.length === 0) return false;
95	
96				// TD Bank CSV has no header, but we can validate the format:
97				// - First row should have 3-4 columns
98				// - First column should be a date
99				// - Second column should be text (description)
100				// - Third column should be a number (amount) OR empty (with 4th column having amount)
101	
102				// Check all rows to ensure consistent format
103				for (const row of rows) {
104					if (row.length < 3 || row.length > 4) return false;
105	
106					const dateStr = row[0]?.trim();
107					if (!dateStr || !this.parseDate(dateStr)) return false;
108	
109					// For 4-column format, either column 3 or 4 should have an amount
110					const debitStr = row[2]?.trim();
111					const creditStr = row.length > 3 ? row[3]?.trim() : '';
112	
113					// At least one should have a valid amount
114					const hasValidAmount =
115						(debitStr && this.parseAmount(debitStr) !== null) ||
116						(creditStr && this.parseAmount(creditStr) !== null);
117	
118					if (!hasValidAmount) return false;
119				}
120	
121				return true;
122			} catch {
123				return false;
124			}
125		}
126	}
