1	import { describe, it, expect } from 'vitest';
2	import { readFileSync } from 'fs';
3	import { join } from 'path';
4	import { TDBankParser } from '../TDBankParser';
5	
6	describe('TDBankParser', () => {
7		const parser = new TDBankParser();
8	
9		// Helper to load CSV files from resources
10		const loadCSV = (filename: string): string => {
11			const filePath = join(process.cwd(), 'resources', filename);
12			return readFileSync(filePath, 'utf-8');
13		};
14	
15		describe('validateFormat', () => {
16			it('should validate correct TD Bank CSV format', () => {
17				const csv = loadCSV('TDBankSample.csv');
18				expect(parser.validateFormat(csv)).toBe(true);
19			});
20	
21			it('should validate format with 4 columns (credit transactions)', () => {
22				const csvWithCredit = `06/11/2024,Store 1,,23.15
23	06/10/2024,No Better,89.19,`;
24				expect(parser.validateFormat(csvWithCredit)).toBe(true);
25			});
26	
27			it('should reject invalid CSV format', () => {
28				const invalidCSV = `Description,Type,Card Holder Name,Date,Time,Amount
29	Test Store,PURCHASE,MARK,06/01/2024,11:59 PM,-100.00`;
30				expect(parser.validateFormat(invalidCSV)).toBe(false);
31			});
32	
33			it('should reject empty CSV', () => {
34				expect(parser.validateFormat('')).toBe(false);
35			});
36	
37			it('should reject CSV with too few columns', () => {
38				const invalidCSV = `06/26/2024,New Store 2`;
39				expect(parser.validateFormat(invalidCSV)).toBe(false);
40			});
41	
42			it('should reject CSV with too many columns', () => {
43				const invalidCSV = `06/26/2024,New Store 2,180.74,10.00,extra`;
44				expect(parser.validateFormat(invalidCSV)).toBe(false);
45			});
46		});
47	
48		describe('parse', () => {
49			it('should parse sample data correctly (#{#trn2e})', () => {
50				const csv = loadCSV('TDBankSample.csv');
51				const result = parser.parse(csv);
52	
53				expect(result.errors).toEqual([]);
54				expect(result.transactions).toHaveLength(42);
55	
56				// Check first transaction (debit, stays negative)
57				expect(result.transactions[0]).toEqual({
58					transaction_date: '2024-06-26',
59					vendor_name: 'New Store 2',
60					amount: -180.74 // Debit (expense), negative = expense
61				});
62	
63				// Check last transaction (debit, stays negative)
64				expect(result.transactions[41]).toEqual({
65					transaction_date: '2024-06-06',
66					vendor_name: 'Store C',
67					amount: -22.6 // Debit (expense), negative = expense
68				});
69			});
70	
71			it('should keep debit transactions as negative amounts (#{#trn2e})', () => {
72				const csv = `06/26/2024,Test Store,100.50,`;
73				const result = parser.parse(csv);
74	
75				expect(result.transactions).toHaveLength(1);
76				expect(result.transactions[0].amount).toBe(-100.5); // Debit stays negative
77			});
78	
79			it('should keep credit transactions as positive amounts (#{#trn2e})', () => {
80				const csv = `06/11/2024,Store 1,,23.15`;
81				const result = parser.parse(csv);
82	
83				expect(result.transactions).toHaveLength(1);
84				expect(result.transactions[0]).toEqual({
85					transaction_date: '2024-06-11',
86					vendor_name: 'Store 1',
87					amount: 23.15 // Credit stays positive
88				});
89			});
90	
91			it('should keep debit amounts without decimals as negative (#{#trn2e})', () => {
92				const csv = `06/24/2024,Store C,85,`;
93				const result = parser.parse(csv);
94	
95				expect(result.transactions[0].amount).toBe(-85); // Debit stays negative
96			});
97	
98			it('should parse dates in MM/DD/YYYY format', () => {
99				const csv = `12/31/2023,Test Store,100.00,`;
100				const result = parser.parse(csv);
101	
102				expect(result.transactions[0].transaction_date).toBe('2023-12-31');
103			});
104	
105			it('should handle dates with single digit month/day', () => {
106				const csv = `1/5/2024,Test Store,50.00,`;
107				const result = parser.parse(csv);
108	
109				expect(result.transactions[0].transaction_date).toBe('2024-01-05');
110			});
111	
112			it('should report errors for invalid dates', () => {
113				const csv = `invalid-date,Test Store,100.00,`;
114				const result = parser.parse(csv);
115	
116				expect(result.errors.length).toBeGreaterThan(0);
117				expect(result.errors[0]).toContain('Invalid date format');
118			});
119	
120			it('should report errors for invalid amounts', () => {
121				const csv = `06/01/2024,Test Store,not-a-number,`;
122				const result = parser.parse(csv);
123	
124				expect(result.errors.length).toBeGreaterThan(0);
125				expect(result.errors[0]).toContain('Invalid amount');
126			});
127	
128			it('should report errors for missing vendor name', () => {
129				const csv = `06/01/2024,,100.00,`;
130				const result = parser.parse(csv);
131	
132				expect(result.errors.length).toBeGreaterThan(0);
133				expect(result.errors[0]).toContain('Missing vendor name');
134			});
135	
136			it('should handle empty CSV', () => {
137				const result = parser.parse('');
138	
139				expect(result.transactions).toEqual([]);
140				expect(result.errors.length).toBeGreaterThan(0);
141			});
142	
143			it('should skip incomplete rows', () => {
144				const csv = `06/01/2024,Test Store,100.00,
145	06/02/2024,Incomplete
146	06/03/2024,Another Store,50.00,`;
147				const result = parser.parse(csv);
148	
149				expect(result.transactions).toHaveLength(2);
150				expect(result.transactions[0].vendor_name).toBe('Test Store');
151				expect(result.transactions[1].vendor_name).toBe('Another Store');
152			});
153	
154			it('should skip empty rows', () => {
155				const csv = `06/01/2024,Test Store,100.00,
156	
157	06/02/2024,Another Store,50.00,`;
158				const result = parser.parse(csv);
159	
160				expect(result.transactions).toHaveLength(2);
161			});
162	
163			it('should handle CSV with BOM', () => {
164				const csv = loadCSV('TDBankSample.csv');
165				const result = parser.parse(csv);
166	
167				expect(result.transactions).toHaveLength(42);
168				expect(result.errors).toEqual([]);
169			});
170	
171			it('should handle mixed debit and credit transactions (#{#trn2e})', () => {
172				const csv = `06/01/2024,Store A,100.00,
173	06/02/2024,Store B,,50.00
174	06/03/2024,Store C,75.00,
175	06/04/2024,Store D,,25.00`;
176				const result = parser.parse(csv);
177	
178				expect(result.transactions).toHaveLength(4);
179				expect(result.transactions[0].amount).toBe(-100.0); // Debit, stays negative
180				expect(result.transactions[1].amount).toBe(50.0); // Credit, stays positive
181				expect(result.transactions[2].amount).toBe(-75.0); // Debit, stays negative
182				expect(result.transactions[3].amount).toBe(25.0); // Credit, stays positive
183			});
184		});
185	});
